/* A local, dependency-free interaction prototype; all figures are game assumptions. */
(() => {
'use strict';
const D=window.MARS_DATA, $=id=>document.getElementById(id), tech=id=>D.techs.find(t=>t.id===id), key=(x,y)=>`${x},${y}`, dist=(a,b)=>Math.max(Math.abs(a.x-b.x),Math.abs(a.y-b.y));
const colors=['#247e86','#8a66a8','#d29838','#728f6c'], resourceNames={ice:'地下氷の候補',iron:'鉄を含む鉱物候補',silica:'ケイ酸塩の候補',regolith:'レゴリス',scrap:'持ち込み資材'};
let state, page='map', selectedTile, selectedTech='ice', showResources=true, fullMap=false, focus=false, lessonTimer=null, lessonStep=0, toastTimer;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function init(){
 const tiles=[];for(let y=0;y<11;y++)for(let x=0;x<11;x++){const n=(x*17+y*31+x*y*7)%37;tiles.push({x,y,terrain:n<5?'ridge':n<8?'crater':'plain',resource:n%11===0?'iron':n%13===0?'silica':n%7===0?'ice':null,owner:null,surveyed:false,improvement:null,blocked:''});}
 const bases=[{x:2,y:7,name:'アレス',owner:0,level:1,growth:0},{x:8,y:8,name:'ヴェスパー',owner:1,level:2,growth:0},{x:8,y:2,name:'ヘリオス',owner:2,level:2,growth:0},{x:2,y:2,name:'ボレアル',owner:3,level:1,growth:0}];
 state={turn:1,dp:12,researched:new Set(['survey','power']),stock:{water:12,oxygen:15,food:18,ice:0,ore:0,regolith:0,hydrogen:0,metal:0,ceramic:0,scrap:5,resin:2,parts:0,methane:0},battery:0,bases,tiles,rover:{x:3,y:7,moved:false},logs:[],storm:false,lastPower:null,units:[{id:1,owner:0,x:2,y:7,hp:3,moved:false},{id:2,owner:1,x:7,y:8,hp:3,moved:false},{id:3,owner:2,x:8,y:3,hp:3,moved:false},{id:4,owner:3,x:2,y:3,hp:3,moved:false}],nextUnitId:5,outcome:null};
 for(const b of bases){const t=tile(b.x,b.y);t.base=b;t.terrain='plain';t.resource=null;claim(b);}
 for(const [x,y,res] of [[2,6,'ice'],[3,7,'iron'],[1,7,'silica'],[3,8,'regolith'],[5,5,'ice'],[7,3,'iron'],[7,8,'ice']]){Object.assign(tile(x,y),{terrain:'plain',resource:res});}
 for(const [x,y] of [[5,7],[5,3]]){Object.assign(tile(x,y),{outpost:true,terrain:'plain',resource:null});}
 tile(1,8).improvement='solar';tile(1,8).surveyed=true;
 for(const t of state.tiles){if(t.owner===0&&t.resource===null)t.surveyed=true;}
 selectedTile=key(2,6);selectedTech='ice';page='map';fullMap=false;focus=false;showResources=true;
 log('◒','着陸。ここから文明が始まる。','船の装置と限られた備蓄を使って、火星で作れるものを増やそう。');render();
}
function tile(x,y){return state.tiles.find(t=>t.x===x&&t.y===y);}
function chosen(){return state.tiles.find(t=>key(t.x,t.y)===selectedTile);}
function ownedBases(){return state.bases.filter(b=>b.owner===0);}
function unitAt(x,y){return state.units.find(u=>u.x===x&&u.y===y);}
function enemyAt(x,y){const u=unitAt(x,y);return u&&u.owner!==0?u:null;}
function rebuildTerritory(){for(const t of state.tiles)t.owner=null;for(const b of state.bases)claim(b);}
function claim(b){const radius=b.level>=2?2:1;for(const t of state.tiles)if(dist(t,b)<=radius&&(t.owner===null||t.owner===b.owner)){t.owner=b.owner;if(b.owner===0&&t.base)t.surveyed=true;}}
function visible(t){return fullMap||ownedBases().some(b=>dist(b,t)<=3)||dist(t,state.rover)<=(state.researched.has('scouting')?4:2);}
function income(){return ownedBases().reduce((n,b)=>n+b.level+2+(state.researched.has('logistics')?1:0),0)+state.tiles.filter(t=>t.owner===0&&t.improvement==='workshop'&&!t.blocked).length*(state.researched.has('metalwork')?2:1);}
function cost(t){return t.cost===0?0:t.cost+(ownedBases().length-1)*(t.col+1);}
function availability(t){return t.deps.every(id=>state.researched.has(id));}
function powerInfo(){const facilities=state.tiles.filter(t=>t.owner===0&&t.improvement),solar=facilities.filter(t=>t.improvement==='solar').length;return {supply:Math.round((4+solar*3)*(state.storm?.4:1)*10)/10,demand:1+facilities.reduce((n,t)=>n+D.improvements[t.improvement].power,0),capacity:facilities.filter(t=>t.improvement==='battery').length*6};}
function log(icon,title,body){state.logs.push({turn:state.turn,icon,title,body});}
function toast(message){$('toast').textContent=message;$('toast').classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.add('hidden'),3600);}
function svgIcon(kind,x=0,y=0,color=colors[0],scale=1){
 let a='';
 if(kind==='base'||kind==='habitat'){a=`<ellipse cy="12" rx="35" ry="14" fill="#573e3825"/><path d="M-28 2Q-28-33 0-33T28 2V12H-28Z" fill="#f1efdf" stroke="#526d6d" stroke-width="2"/><path d="M-27 2H27M0-31V2" stroke="#aac8c6" stroke-width="2"/><path d="M-14-20Q0-28 14-20V-6H-14Z" fill="#8db7bc"/><path d="M-32 10L0 24 32 10V20L0 34-32 20Z" fill="#d1baa1" stroke="#775c4e"/><path d="M29-13V-48" stroke="#49565b" stroke-width="3"/><path d="M30-48H51L45-39H30Z" fill="${color}"/>`;}
 else if(kind==='patrol'){a=`<ellipse cy="14" rx="28" ry="11" fill="#4c393930"/><path d="M-25-2L0-14 25-2 0 10Z" fill="${color}" stroke="#435959" stroke-width="2"/><path d="M-25-2V11L0 24V10Z" fill="#405b5c"/><path d="M0 10L25-2V11L0 24Z" fill="#89b4aa"/><circle cx="-17" cy="18" r="6" fill="#203c42"/><circle cx="17" cy="17" r="6" fill="#203c42"/><path d="M0-14v-15m-13 8h26" stroke="#edf4dd" stroke-width="3"/><circle cx="0" cy="-29" r="4" fill="#f5c87e"/>`;}
 else if(kind==='rover'){a=`<ellipse cy="12" rx="26" ry="10" fill="#4c393930"/><path d="M-22-2L5-13 26-2 0 10Z" fill="#ece8d5" stroke="#59706d" stroke-width="2"/><path d="M-22-2V10L0 22V10Z" fill="${color}"/><path d="M0 10L26-2V10L0 22Z" fill="#bcc9bb"/><circle cx="-16" cy="14" r="6" fill="#394d50"/><circle cx="3" cy="22" r="6" fill="#394d50"/><circle cx="21" cy="13" r="6" fill="#394d50"/><path d="M4-7V-27L17-33" stroke="#5d706d" stroke-width="3"/><circle cx="18" cy="-34" r="4" fill="${color}"/>`;}
 else if(kind==='ice'){a=`<path d="M-21 5L-15-20-2-28 9-7 20-19 30 7 0 21Z" fill="#acd5d9" stroke="#6cabb5" stroke-width="2"/><path d="M-2-28L0 21 9-7M20-19L20 10" stroke="#e2f4ed" stroke-width="3" fill="none"/>`;}
 else if(kind==='iron'||kind==='mine'){a=`<path d="M-28 8L-14-20 7-26 30 1 19 19-10 22Z" fill="#914f48" stroke="#75483e" stroke-width="2"/><path d="M-14-20L-3 1 7-26M-3 1L19 19 30 1" stroke="#be8a65" stroke-width="3" fill="none"/><circle cx="-10" cy="9" r="3" fill="#e2b478"/>`;}
 else if(kind==='silica'||kind==='glass'){a=`<path d="M-21 9L-14-20 0-29 12-5 25 12 1 22Z" fill="#e9d4a6" stroke="#ac9470" stroke-width="2"/><path d="M0-29L1 22 12-5" fill="none" stroke="#fff0c7" stroke-width="3"/>`;}
 else if(kind==='solar'){a=`<path d="M-29 1L8-17 37-2 0 18Z" fill="#537c94" stroke="#364f67" stroke-width="2"/><path d="M-16 7L21-10M-3 13L33-4M-17-5L12 10M-5-11L24 4" stroke="#94b8ca" stroke-width="1.5"/><path d="M0 18V29M25 6V17" stroke="#5b6864" stroke-width="3"/>`;}
 else if(kind==='greenhouse'){a=`<path d="M-28 7Q-28-24 0-24T28 7V18H-28Z" fill="#bed3ad" stroke="#618577" stroke-width="2"/><path d="M-15-19V18M0-24V18M15-19V18" stroke="#edf0d3" stroke-width="3"/><path d="M-18 10l8-11 8 13 10-15 10 15" fill="none" stroke="#62865c" stroke-width="4"/>`;}
 else if(kind==='outpost'){a=`<path d="M-23 12L0-17 23 12 0 24Z" fill="#d4c3a3" stroke="#9a8f76" stroke-width="2"/><path d="M0-17V24L12 16Z" fill="#a59a82"/><path d="M0-17V-40H21L17-31H0" fill="#f5ebc9" stroke="#8e8a71" stroke-width="2"/>`;}
 else if(kind==='ridge'){a=`<path d="M-39 18L-12-40 7-21 20-48 43 10 9 32Z" fill="#b87c5c" stroke="#98664f" stroke-width="2"/><path d="M-12-40L-3 17 7-21 20-48 24 25" fill="#d39b70"/><path d="M-12-40L-22-18-8-24ZM20-48L13-31 25-34Z" fill="#e6b987"/>`;}
 else if(kind==='crater'){a=`<ellipse cy="7" rx="30" ry="15" fill="#9c6858"/><ellipse cy="3" rx="26" ry="12" fill="#e2ad81"/><ellipse cy="5" rx="18" ry="8" fill="#ab735a"/>`;}
 else if(kind==='regolith'){a=`<path d="M-27 12L-13-8 12-15 29 10 9 22Z" fill="#cea177"/><circle cx="-9" cy="9" r="4" fill="#9b755a"/><circle cx="10" cy="0" r="5" fill="#e8c39b"/>`;}
 else {a=`<path d="M-24-5L0-18 25-5 0 8Z" fill="#e6daca" stroke="#7c8981" stroke-width="2"/><path d="M-24-5V19L0 32V8Z" fill="#9eb9ad"/><path d="M0 8L25-5V19L0 32Z" fill="#6e9690"/><path d="M-12-8V-31H3V-15" fill="#cbd1bf" stroke="#7c8981" stroke-width="2"/><rect x="5" y="8" width="9" height="12" fill="${color}"/>`;}
 return `<g transform="translate(${x} ${y}) scale(${scale})">${a}</g>`;
}
function renderMap(){
 let s=`<defs><filter id="mapShadow"><feDropShadow dx="0" dy="15" stdDeviation="14" flood-color="#604331" flood-opacity=".13"/></filter></defs><ellipse cx="560" cy="408" rx="451" ry="236" fill="#9e765e" opacity=".055"/>`;
 let labels='';
 const tiles=[...state.tiles].sort((a,b)=>(a.x+a.y)-(b.x+b.y)||a.x-b.x);
 for(const t of tiles){const cx=560+(t.x-t.y)*46,cy=90+(t.x+t.y)*24,seen=visible(t),selected=key(t.x,t.y)===selectedTile;const palette=['#dbab7c','#dfb78a','#cfa076','#e5ba8a'];let fill=seen?palette[(t.x*3+t.y)%4]:'#e4e5db';if(t.owner===0&&seen)fill='#c5c7a0';else if(t.owner!==null&&seen)fill=['','#c9b7c5','#dfc091','#bac6aa'][t.owner];
 s+=`<g class="tile-hit ${selected?'selected-tile':''}" data-tile="${t.x},${t.y}" tabindex="0" role="button" aria-label="${esc(`${t.x+1},${t.y+1} ${seen?(t.base?t.base.name:resourceNames[t.resource]||'平地'):'未探査'}`)}"><title>${seen?(t.base?t.base.name:resourceNames[t.resource]||'平地'):'未探査'}</title><path d="M${cx-46} ${cy}l46 24 46-24v16l-46 24-46-24Z" fill="${seen?'#b78965':'#cbd3c9'}" stroke="${seen?'#a17d61':'#c0c9bf'}" stroke-width=".8"/><path d="M${cx} ${cy-24}l46 24-46 24-46-24Z" fill="${fill}" stroke="${selected?'#fff5c2':t.owner!==null&&seen?colors[t.owner]+'99':'#b58c6b88'}" stroke-width="${selected?4:t.owner!==null?1.6:1}"/>`;
 if(!seen){s+=`<path d="M${cx-17} ${cy-1}q0-12 10-12 4-14 16-8 15-1 15 13 15 3 10 13h-50q-10-4-1-6" fill="#f8faf0" opacity=".85"/>`;}
 else{if(t.base)s+=svgIcon('base',cx,cy-17,colors[t.owner],.87);else if(t.outpost)s+=svgIcon('outpost',cx,cy-8,'#afa58c',.8);else if(t.improvement)s+=svgIcon(t.improvement,cx,cy-14,colors[t.owner],.75);else if(t.terrain==='ridge')s+=svgIcon('ridge',cx,cy-5,'',.85);else if(t.terrain==='crater')s+=svgIcon('crater',cx,cy-4,'',.85);else if(t.resource&&showResources){s+=svgIcon(t.resource,cx,cy-7,'',.73);if(!t.surveyed)s+=`<circle cx="${cx+24}" cy="${cy-22}" r="10" fill="#fbf2d9" stroke="#c7af83"/><text x="${cx+24}" y="${cy-18}" text-anchor="middle" font-size="12" fill="#8c7354">?</text>`;}
 if(t.x===state.rover.x&&t.y===state.rover.y)s+=svgIcon('rover',cx+6,cy-23,colors[0],.9);
  const patrol=unitAt(t.x,t.y);if(patrol){s+=svgIcon('patrol',cx-12,cy-38,colors[patrol.owner],.73);s+=`<g pointer-events="none"><circle cx="${cx+15}" cy="${cy-57}" r="12" fill="${colors[patrol.owner]}"/><text x="${cx+15}" y="${cy-53}" text-anchor="middle" font-size="11" fill="white">${patrol.hp}</text></g>`;}
 if(t.base)labels+=`<g pointer-events="none" transform="translate(${cx} ${cy+40})"><rect x="-53" y="-2" width="106" height="33" rx="8" fill="${colors[t.owner]}"/><text x="0" y="12" text-anchor="middle" font-size="11" fill="white" font-weight="700">${t.base.name} Lv.${t.base.level}</text><text x="0" y="25" text-anchor="middle" font-size="8" fill="#e9f1db">${t.owner===0?'✦ +'+(t.base.level+2)+'/ターン':'他勢力の拠点'}</text></g>`;
 if(t.blocked)s+=`<circle cx="${cx+23}" cy="${cy-20}" r="9" fill="#b56d49"/><text x="${cx+23}" y="${cy-17}" text-anchor="middle" font-size="11" fill="white">!</text>`;
 }
 s+='</g>';
 }
 $('world').innerHTML=s+labels;
 $('weather').textContent=state.storm?'≋ 砂嵐 · 太陽光発電が低下':'☀ 晴天 · 探査日和';$('weather').classList.toggle('storm',state.storm);$('mission').textContent=state.turn<=4?'MISSION 01 · 砂嵐に備える':state.turn<=6?'MISSION 01 · 砂嵐をしのぐ':state.turn===7?'次の展開 · 他勢力が動き出す':state.outcome==='victory'?'開拓完了':state.outcome==='defeat'?'開拓終了':'拠点を守り、火星の素材を広げる';
 $('resource-btn').classList.toggle('selected',showResources);$('fog-btn').classList.toggle('selected',fullMap);$('fog-btn').textContent=fullMap?'探査済みだけを見る':'全域を見る';renderTilePanel();
}
function btn(action,text,price,disabled=false,sub='',accent=false){return `<button class="action ${accent?'accent':''}" data-action="${action}" ${disabled?'disabled':''}><span>${text}${sub?`<small>${sub}</small>`:''}</span>${price!==null?`<b>✦ ${price}</b>`:''}</button>`;}
function nearestBase(t){return ownedBases().sort((a,b)=>dist(t,a)-dist(t,b))[0];}
function canSurvey(t){return !t.surveyed&&dist(t,state.rover)<=1&&state.dp>=1&&(t.resource!=='iron'&&t.resource!=='silica'||state.researched.has('mineral'));}
function buildReason(t,id){const v=D.improvements[id];if(!v)return '設備がありません';if(t.owner!==0)return '自分の領地で建設できます';if(t.base||t.outpost||t.terrain==='ridge'||t.terrain==='crater')return 'この土地には建てられません';if(t.improvement&&t.improvement!==v.upgrade)return 'すでに設備があります';if(!state.researched.has(v.tech))return '研究が必要です';if(v.resource&&t.resource!==v.resource)return '適した資源マスが必要です';if(v.resource&&!t.surveyed)return '現地調査が必要です';if(v.upgrade&&t.improvement!==v.upgrade)return '採取場を先に建てます';if(state.dp<v.cost)return '開発ポイントが足りません';if(v.materials&&Object.entries(v.materials).some(([k,n])=>state.stock[k]<n))return '製作材料が足りません';return '';}
function renderTilePanel(){const t=chosen();if(!t)return;const known=visible(t),patrol=unitAt(t.x,t.y),name=!known?'未探査の土地':t.base?`${t.base.name}基地`:t.outpost?'無人の前哨基地':t.improvement?D.improvements[t.improvement].name:t.resource?resourceNames[t.resource]:t.terrain==='ridge'?'岩の稜線':t.terrain==='crater'?'クレーター':'開拓できる平地';
 let s=`<p class="eyebrow">SELECTED TILE · ${t.x+1} / ${t.y+1}</p><h2>${name}</h2><span class="tag ${t.owner===null?'gold':t.owner!==0?'gray':''}">${t.owner===0?'あなたの領地':t.owner===null?'未開拓': '他勢力の領地'}</span> <span class="tag gray">${t.surveyed?'調査済み':'現地では未確認'}</span><div class="tile-portrait"><svg viewBox="-90 -70 180 120">${svgIcon(t.base?'base':t.outpost?'outpost':t.improvement||t.resource||t.terrain,0,0,t.owner===null?colors[0]:colors[t.owner],1.4)}</svg></div>`;
 s+=`<p>${!known?'ローバーで近づくと、地形と資源の候補が見えてきます。':t.resource&&!t.surveyed?'資源の候補を見つけました。現地で調べて、利用できる材料か確認しましょう。':t.base?'周囲の土地を開発すると発展度が上がります。拠点が育つと、収入と領地が増えます。':t.outpost?'探査ローバーをこのマスに移動させると、新しい拠点を確保できます。':t.improvement?'次のターンから材料や電力を供給します。動作には必要な入力と電力が必要です。':'研究を進めると、この場所に作れる設備が増えていきます。'}</p>`;
 if(t.base)s+=`<div class="metrics"><div class="metric">発展度<b>${t.base.growth} / ${t.base.level+2}</b></div><div class="metric">収入<b>✦ ${t.base.level+2} / ターン</b></div></div>`;
 if(patrol)s+=`<div class="metric">${patrol.owner===0?'あなたの':'他勢力の'}巡回ローバー <b>耐久 ${patrol.hp}/3 ${patrol.owner===0?(patrol.moved?'・行動済み':'・行動可能'):''}</b></div>`;
 if(t.base&&t.base.owner!==0)s+=`<div class="metric">拠点の防備<b>${t.base.hp||3}/3</b></div>`;
 if(t.improvement){const i=D.improvements[t.improvement];s+=`<div class="metrics"><div class="metric">必要な電力<b>${i.power}</b></div><div class="metric">稼働状況<b>${t.blocked||'準備OK'}</b></div></div><p class="note">${Object.entries(i.input||{}).map(([k,n])=>D.names[k]+' '+n).join(' + ')||'現地資源・設備'} → ${Object.entries(i.output).map(([k,n])=>D.names[k]+' '+n).join(' + ')||(t.improvement==='solar'?'発電 +3':t.improvement==='battery'?'蓄電容量 +6':'拠点の発展')}</p>`;}
 s+='<div class="actions">';
 if(t.base&&t.base.owner===0&&!patrol)s+=btn('recruit','巡回ローバーを製作',4,state.dp<4||state.stock.resin+state.stock.parts<1,'樹脂か部品を1つ使う',true);
 if(known&&!patrol&&!t.base&&t.terrain!=='ridge'){for(const u of state.units.filter(u=>u.owner===0&&!u.moved&&dist(u,t)===1))s+=btn('patrol:'+u.id,'巡回ローバーを移動',null,false,'隣の土地へ');}
 if(known&&(patrol&&patrol.owner!==0||t.base&&t.base.owner!==0)&&state.units.some(u=>u.owner===0&&!u.moved&&dist(u,t)===1))s+=btn('attack','巡回ローバーで攻撃',null,false,'相手の機体・拠点を狙う',true);
 const moveRange=state.researched.has('wheels')?2:1;
 if(known&&dist(t,state.rover)>0&&dist(t,state.rover)<=moveRange)s+=btn('move','探査ローバーを移動',null,state.rover.moved||(t.terrain==='ridge'&&!state.researched.has('wheels')),'1ターンに1回');
 if(known&&!t.surveyed&&dist(t,state.rover)<=1){if((t.resource==='iron'||t.resource==='silica')&&!state.researched.has('mineral'))s+=btn('tech:mineral','鉱物分析の研究を見る',cost(tech('mineral')),false);else s+=btn('survey','現地を調べる',1,!canSurvey(t),'候補を、使える素材へ',true);}
 if(t.outpost&&t.x===state.rover.x&&t.y===state.rover.y)s+=btn('claim','拠点を確保する',3,state.dp<3,'領地と収入が増える',true);
 if(known&&t.owner===0&&!t.base&&!t.outpost&&t.terrain==='plain'){
 if(t.resource==='ice'&&!state.researched.has('ice'))s+=btn('tech:ice','氷の採取を研究する',cost(tech('ice')),false,'研究ページへ',true);
 if(t.improvement==='iceMine'&&!state.researched.has('water'))s+=btn('tech:water','水を得る技術を研究',cost(tech('water')),false,'採取した氷の次の使い道',true);
 const ids=Object.keys(D.improvements).filter(id=>{const v=D.improvements[id];return state.researched.has(v.tech)&&(!v.resource||v.resource===t.resource)&&(!t.improvement||v.upgrade===t.improvement)&&(!v.upgrade||t.improvement===v.upgrade);});
 for(const id of ids){const v=D.improvements[id],reason=buildReason(t,id);s+=btn('build:'+id,v.name+(v.upgrade?'へ改良':'を建てる'),v.cost,!!reason,reason||`発展度 +${v.growth}${v.power?' / 電力 '+v.power:''}`);}
 }
 s+='</div><div class="section-title">基地の素材倉庫</div><div class="inventory">';for(const [k,v] of Object.entries(state.stock)){if(!['water','oxygen','food'].includes(k)&&(v>0||['ice','ore','parts'].includes(k)))s+=`<span>${D.names[k]} <b>${v}</b></span>`;}s+='</div>';
 s+=`<div class="tip">${state.researched.has('ice')?'発明は別ページの研究ロードマップから。今は使えない素材にも、次の技術で用途が生まれます。':'最初の目標：氷の候補を調べ、研究ページで「氷の採取」を選んでみよう。'}</div><p class="note">地図・資源量・数量単位は試作用の仮定。NASAの観測地図とは別の仮想地域です。</p>`;
 $('tile-panel').innerHTML=s;
}
function renderTree(){
 let s='';const xy=t=>({x:155+t.col*234,y:82+t.row*128});
 ['01 発見する','02 加工する','03 応用する','04 文明へ'].forEach((v,i)=>s+=`<text x="${155+i*234}" y="36" fill="#8b9386" font-size="14" font-weight="700">${v}</text>`);
 for(const t of D.techs){const end=xy(t);for(const id of t.deps){const p=tech(id),start=xy(p),cross=p.row!==t.row,hi=t.id===selectedTech;let path;if(cross){const mid=start.x+214+(p.row<t.row?5:13);path=`M${start.x+202} ${start.y+44}H${mid}V${end.y-10}H${end.x+14}V${end.y}`;}else path=`M${start.x+202} ${start.y+44}H${end.x}`;s+=`<path d="${path}" fill="none" stroke="${hi?'#337d88':cross?'#9aaeb6':'#bdc6b8'}" stroke-width="${hi?3:1.5}" ${cross?'stroke-dasharray="5 5"':''} opacity="${hi?1:cross?.5:.9}"/>`;}}
 for(let row=0;row<6;row++){const [label,color]=D.branches[row];s+=`<circle cx="23" cy="${126+row*128}" r="5" fill="${color}"/><text x="38" y="${131+row*128}" fill="${color}" font-size="13" font-weight="700">${label}</text>`;}
 for(const t of D.techs){const p=xy(t),done=state.researched.has(t.id),ready=availability(t),sel=t.id===selectedTech,dim=focus&&!ready&&!done;const fill=done?'#e0ede1':ready?'#fffdf4':'#eceee5',stroke=sel?'#1c7e82':done?'#70a198':ready?'#c4a05d':'#d4d9cc';s+=`<g data-tech="${t.id}" tabindex="0" role="button" aria-label="${esc(t.name+' '+(done?'研究済み':ready?'研究可能':'前提研究が必要'))}" opacity="${dim?.27:1}" style="cursor:pointer"><rect x="${p.x}" y="${p.y}" width="202" height="91" rx="13" fill="${fill}" stroke="${stroke}" stroke-width="${sel?3:1.5}"/><circle cx="${p.x+28}" cy="${p.y+28}" r="16" fill="${done?'#2c8584':D.branches[t.row][1]}" opacity="${done?1:.8}"/><text x="${p.x+28}" y="${p.y+34}" text-anchor="middle" fill="white" font-size="${t.symbol.length>2?10:16}">${t.symbol}</text><text x="${p.x+52}" y="${p.y+33}" fill="#284147" font-size="14" font-weight="700">${esc(t.name)}</text><text x="${p.x+16}" y="${p.y+68}" fill="${done?'#2a8280':ready?'#a27a35':'#87928b'}" font-size="12">${done?'✓ 研究済み':ready?'✦ '+cost(t)+' / 研究できる':'前提 '+t.deps.filter(id=>!state.researched.has(id)).length+'件'}</text><text x="${p.x+184}" y="${p.y+69}" text-anchor="end" fill="#8c9c93" font-size="11">▷</text></g>`;}
 $('tree').innerHTML=s;$('focus-btn').classList.toggle('selected',focus);renderTechPanel();
}
function renderTechPanel(){const t=tech(selectedTech),done=state.researched.has(t.id),ready=availability(t);$('tech-panel').innerHTML=`<p class="eyebrow">${D.branches[t.row][0]} / RESEARCH</p><h2>${t.name}</h2><span class="tag ${done?'':ready?'gold':'gray'}">${done?'研究済み':ready?'研究できる':'前提研究が必要'}</span><p>${t.benefit}</p><div class="section-title">必要な前提研究</div><div class="prereqs">${t.deps.map(id=>`<button data-tech="${id}" class="${state.researched.has(id)?'met':''}">${state.researched.has(id)?'✓ ':''}${tech(id).name}</button>`).join('')||'<span class="note">初期装備から始められます</span>'}</div><div class="section-title">使う素材・装置</div><p>${t.inputs}</p><div class="actions">${done?btn('back-map','地図で使ってみる →',null,false,'基地や土地を選ぼう',true):btn('research','この技術を研究する',cost(t),!ready||state.dp<cost(t),!ready?'先につながる技術を研究しよう':state.dp<cost(t)?'次のターンの収入を待とう':'地図上の選択肢が増える',true)}</div><div class="learning"><h3>▷ 仕組みを見てみよう</h3><div class="lesson-stage" id="lesson-stage"></div><div class="lesson-dots" id="lesson-dots"></div><div class="lesson-controls"><button id="play-lesson">▶ ミニ解説を再生</button><button id="next-lesson">次へ →</button></div><p class="note">文字と記号で学ぶ3コマのミニ解説。何度でも確認できます。</p></div>${t.id==='electrolysis'?'<div class="formula">2H₂O → 2H₂ + O₂</div>':t.id==='iron'?'<div class="formula">Fe₂O₃ + 3H₂ → 2Fe + 3H₂O</div>':''}<p>${t.fact}</p><div class="science-badge">${t.status}</div><p class="note"><a href="${t.source}" target="_blank" rel="noopener">科学の参考資料 ↗</a></p>`;renderLesson();}
function renderLesson(){const t=tech(selectedTech);if(!$('lesson-stage'))return;const symbols=t.id==='electrolysis'?['H₂O ＋ ϟ','H₂ ← ▣ → O₂','基地 ← O₂ / H₂ → 発明']:['① '+t.symbol,'② '+t.symbol,'③ '+t.symbol];$('lesson-stage').innerHTML=`<div><span class="stage-symbol">${symbols[lessonStep]}</span><span class="stage-text">${t.steps[lessonStep]}</span></div>`;$('lesson-dots').innerHTML=t.steps.map((_,i)=>`<i class="${i===lessonStep?'active':''}"></i>`).join('');if($('play-lesson'))$('play-lesson').textContent=lessonTimer?'Ⅱ 一時停止':'▶ ミニ解説を再生';}
function stopLesson(){clearInterval(lessonTimer);lessonTimer=null;}
function selectTech(id){if(!tech(id))return;stopLesson();lessonStep=0;selectedTech=id;renderTree();}
function switchPage(next){stopLesson();page=next;$('map-page').classList.toggle('hidden',page!=='map');$('research-page').classList.toggle('hidden',page!=='research');$('map-tab').classList.toggle('active',page==='map');$('research-tab').classList.toggle('active',page==='research');$('map-tab').setAttribute('aria-selected',String(page==='map'));$('research-tab').setAttribute('aria-selected',String(page==='research'));page==='map'?renderMap():renderTree();}
function render(){const p=powerInfo();$('points').textContent=state.dp;$('income').textContent=`+${income()} / ターン`;$('water').textContent=state.stock.water;$('oxygen').textContent=state.stock.oxygen;$('food').textContent=state.stock.food;$('power').textContent=`${p.supply} / ${p.demand}`;$('power').title='発電 / 需要。蓄電 '+state.battery+' / '+p.capacity;$('turn').textContent=`${state.turn}`;$('turn-btn').disabled=!!state.outcome;$('outcome').textContent=state.outcome==='victory'?'★ 開拓に成功':state.outcome==='defeat'?'× 拠点を失った':'';$('outcome').classList.toggle('hidden',!state.outcome);$('research-count').textContent=`${state.researched.size}/${D.techs.length}`;$('log-count').textContent=state.logs.length;switchPage(page);}
function doResearch(){const t=tech(selectedTech);if(state.researched.has(t.id))return false;if(!availability(t)||state.dp<cost(t)){toast('前提研究と開発ポイントを確認しよう。');return false;}state.dp-=cost(t);state.researched.add(t.id);log(t.symbol,t.name+'を研究した',t.benefit);render();toast(t.name+'を研究しました。地図で使い道を見てみよう。');return true;}
function develop(t,n){const b=nearestBase(t);if(!b)return;b.growth+=n;while(b.growth>=b.level+2){b.growth-=b.level+2;b.level++;claim(b);log('⌂',b.name+'がレベル'+b.level+'に成長','領地と開発ポイントの収入が増えた。次に何を作ろう。');}}
function build(id){const t=chosen(),reason=buildReason(t,id);if(reason){toast(reason);return false;}const v=D.improvements[id];state.dp-=v.cost;for(const [k,n] of Object.entries(v.materials||{}))state.stock[k]-=n;t.improvement=id;t.blocked='';develop(t,v.growth);log('▣',v.name+'が完成',`アレスの開拓が進んだ。必要な電力と材料をそろえて稼働させよう。`);render();toast(v.name+'が完成しました。');return true;}
function survey(){const t=chosen();if(!canSurvey(t)){toast('探査ローバーの位置、必要な研究、ポイントを確認しよう。');return false;}state.dp--;t.surveyed=true;log('⌖','現地調査が完了',`${resourceNames[t.resource]||'この土地'}の利用条件を確認した。`);render();toast('調査できました。研究を進めて素材を使おう。');return true;}
function move(){const t=chosen(),range=state.researched.has('wheels')?2:1;if(state.rover.moved||dist(t,state.rover)>range||dist(t,state.rover)===0||t.terrain==='ridge'&&!state.researched.has('wheels')||t.owner!==null&&t.owner!==0||unitAt(t.x,t.y)){toast('このターンはそこへ移動できません。');return false;}state.rover.x=t.x;state.rover.y=t.y;state.rover.moved=true;render();toast('探査ローバーが移動しました。周囲の候補を調べられます。');return true;}
function claimOutpost(){const t=chosen();if(!t.outpost||t.x!==state.rover.x||t.y!==state.rover.y||state.dp<3)return false;state.dp-=3;t.outpost=false;const b={x:t.x,y:t.y,owner:0,level:1,growth:0,name:'前哨基地 '+ownedBases().length};state.bases.push(b);t.base=b;t.owner=0;t.surveyed=true;claim(b);log('⚑','新しい拠点を確保',b.name+'が加わった。収入が増え、研究費も拠点数に応じて上がる。');render();return true;}
function recruit(){const t=chosen();if(state.outcome||!t.base||t.base.owner!==0||unitAt(t.x,t.y)||state.dp<4||state.stock.resin+state.stock.parts<1){toast('基地の空き、材料、開発ポイントを確認しよう。');return false;}state.dp-=4;state.stock.resin>0?state.stock.resin--:state.stock.parts--;const u={id:state.nextUnitId++,owner:0,x:t.x,y:t.y,hp:3,moved:true};state.units.push(u);log('⚑','巡回ローバーを製作',`樹脂または部品を使って、拠点の守りを増やした。`);render();return true;}
function movePatrol(id){const t=chosen(),u=state.units.find(v=>v.id===id);if(state.outcome||!u||u.owner!==0||u.moved||dist(u,t)!==1||t.terrain==='ridge'||t.base||unitAt(t.x,t.y)){toast('巡回ローバーはこの土地へ移動できません。');return false;}u.x=t.x;u.y=t.y;u.moved=true;render();return true;}
function finishCombat(winner,loserBase){if(loserBase){const old=loserBase.owner;loserBase.owner=winner;loserBase.hp=3;if(!state.bases.some(b=>b.owner===old))state.units=state.units.filter(u=>u.owner!==old);rebuildTerritory();log('⚑',`${loserBase.name}を確保`,`資源と開発をめぐる競争の結果、拠点の所属が変わった。`);}if(!ownedBases().length){state.outcome='defeat';log('×','開拓はここまで','すべての拠点を失った。ルールからやり直せる。');}else if(!state.bases.some(b=>b.owner!==0)){state.outcome='victory';log('★','火星の開拓に成功','すべての競争拠点を確保した。科学と生産の道も広げられる。');}}
function attack(){const t=chosen(),enemy=enemyAt(t.x,t.y),base=t.base&&t.base.owner!==0?t.base:null,u=state.units.find(v=>v.owner===0&&!v.moved&&dist(v,t)===1);if(state.outcome||!u||!enemy&&!base){toast('攻撃できる対象が隣にありません。');return false;}u.moved=true;if(enemy){enemy.hp--;log('⚡','巡回機どうしが交戦',`${t.x+1},${t.y+1}の土地で機体を攻撃した。`);if(enemy.hp<=0){state.units=state.units.filter(v=>v!==enemy);log('⚑','相手の機体を停止','材料と電力の投資が、土地を守る力になった。');}}else{base.hp=(base.hp||3)-1;log('⚡',`${base.name}へ攻撃`,`拠点の防備が${base.hp}/3になった。`);if(base.hp<=0)finishCombat(0,base);}render();return true;}
function enemyPhase(){if(state.outcome||state.turn<8)return;for(const u of [...state.units].filter(v=>v.owner!==0)){if(state.outcome)break;if(!state.units.includes(u))continue;const target=ownedBases().sort((a,b)=>dist(u,a)-dist(u,b))[0];if(!target)break;const defenders=state.units.filter(v=>v.owner===0&&dist(u,v)===1);if(defenders.length){const v=defenders[0];v.hp--;if(v.hp<=0){state.units=state.units.filter(w=>w!==v);log('⚡','巡回ローバーが停止',`他勢力との交戦で機体を失った。工房の材料をどう使うかが重要になる。`);}continue;}if(dist(u,target)===1){target.hp=(target.hp||3)-1;log('⚠',`${target.name}が攻撃された`,`防備は${target.hp}/3。巡回ローバーで守ろう。`);if(target.hp<=0)finishCombat(u.owner,target);continue;}const options=state.tiles.filter(t=>dist(u,t)===1&&t.terrain!=='ridge'&&!t.base&&!unitAt(t.x,t.y));options.sort((a,b)=>dist(a,target)-dist(b,target));if(options.length){u.x=options[0].x;u.y=options[0].y;const t=tile(u.x,u.y);if(t.outpost){t.outpost=false;const b={x:t.x,y:t.y,owner:u.owner,level:1,growth:0,hp:3,name:`${['アレス','ヴェスパー','ヘリオス','ボレアル'][u.owner]}前哨地`};state.bases.push(b);t.base=b;claim(b);log('⚑','他勢力が前哨地を確保',`${b.name}が建ち、地図上の競争が進んだ。`);}}}
 for(const b of state.bases.filter(v=>v.owner!==0)){if(state.turn%4===0&&!state.units.some(u=>u.owner===b.owner)&&!unitAt(b.x,b.y))state.units.push({id:state.nextUnitId++,owner:b.owner,x:b.x,y:b.y,hp:3,moved:false});}
}
function endTurn(){
 if(state.outcome)return;stopLesson();state.turn++;state.dp+=income();state.rover.moved=false;for(const u of state.units.filter(v=>v.owner===0)){u.moved=false;if(u.hp<3&&tile(u.x,u.y).owner===0)u.hp++;}const oldStorm=state.storm;state.storm=state.turn===5||state.turn===6||state.turn>12&&state.turn%12===5;
 if(state.turn===3)log('≋','砂嵐の予報','ターン5から発電が落ちる見込み。蓄電、備蓄、設備の優先順位を考えよう。');
 if(state.storm&&!oldStorm)log('≋','砂嵐が到来','太陽光発電が低下。必要な設備に電力を使おう。');
 if(oldStorm&&!state.storm)log('☀','空が晴れた','発電が戻った。次の発明に向けて基地を育てよう。');
 if(state.turn===7)log('⚑','次の開拓競争','砂嵐を越えた。次のターンから他勢力の巡回ローバーが動く。');
 const p=powerInfo();let available=Math.max(0,p.supply-1);const capacity=p.capacity;state.battery=Math.min(state.battery,capacity);
 const facilities=state.tiles.filter(t=>t.owner===0&&t.improvement).sort((a,b)=>{const rank={waterPlant:0,oxygenPlant:1,greenhouse:2};return (rank[a.improvement]??3)-(rank[b.improvement]??3);});
 for(const t of facilities){const i=D.improvements[t.improvement];t.blocked='';if(Object.entries(i.input||{}).some(([k,n])=>state.stock[k]<n)){t.blocked='材料不足';continue;}const need=Math.max(0,i.power-available);if(need>state.battery+.0001){t.blocked='電力不足';continue;}available=Math.max(0,available-i.power);state.battery=Math.round((state.battery-need)*10)/10;for(const [k,n] of Object.entries(i.input||{}))state.stock[k]-=n;for(const [k,n] of Object.entries(i.output))state.stock[k]+=n;}
 state.battery=Math.round(Math.min(capacity,state.battery+available)*10)/10;
 for(const k of ['water','oxygen','food'])state.stock[k]=Math.max(0,Math.round((state.stock[k]-(k==='food'?.5:1))*10)/10);
 const empty=['water','oxygen','food'].filter(k=>state.stock[k]===0);if(empty.length)log('!','生命維持の供給が必要',empty.map(k=>D.names[k]).join('・')+'が不足。試作ではゲームオーバーにせず、設備改善を続けられます。');
 enemyPhase();render();toast(state.outcome==='victory'?'開拓に成功しました。':state.outcome==='defeat'?'拠点を失いました。':'ターン'+state.turn+'。収入と設備の生産を確認しよう。');
}
function handleAction(action){if(state.outcome&&!['back-map'].includes(action)){toast('開拓の結果が決まりました。「最初から」で再挑戦できます。');return;}if(action.startsWith('tech:')){selectedTech=action.split(':')[1];lessonStep=0;switchPage('research');}else if(action.startsWith('build:'))build(action.split(':')[1]);else if(action.startsWith('patrol:'))movePatrol(Number(action.split(':')[1]));else ({research:doResearch,survey,move,claim:claimOutpost,recruit,attack,'back-map':()=>switchPage('map')})[action]?.();}
function openStory(){$('story-content').innerHTML=[...state.logs].reverse().map(l=>`<article class="story-card"><div class="story-icon">${l.icon}</div><div><small>TURN ${l.turn}</small><h3>${l.title}</h3><p>${l.body}</p></div></article>`).join('');$('story-dialog').showModal();}
document.addEventListener('click',e=>{const tileEl=e.target.closest('[data-tile]');if(tileEl){selectedTile=tileEl.dataset.tile;renderMap();return;}const te=e.target.closest('[data-tech]');if(te){selectTech(te.dataset.tech);return;}const a=e.target.closest('[data-action]');if(a&&!a.disabled){handleAction(a.dataset.action);return;}const close=e.target.closest('[data-close]');if(close)$(close.dataset.close).close();if(e.target.id==='play-lesson'){if(lessonTimer)stopLesson();else lessonTimer=setInterval(()=>{lessonStep=(lessonStep+1)%3;renderLesson();},3500);renderLesson();}if(e.target.id==='next-lesson'){stopLesson();lessonStep=(lessonStep+1)%3;renderLesson();}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-tile],[data-tech]')&&e.target.tagName.toLowerCase()!=='button'){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
$('map-tab').onclick=()=>switchPage('map');$('research-tab').onclick=()=>switchPage('research');$('turn-btn').onclick=endTurn;$('resource-btn').onclick=()=>{showResources=!showResources;renderMap();};$('fog-btn').onclick=()=>{fullMap=!fullMap;renderMap();};$('focus-btn').onclick=()=>{focus=!focus;renderTree();};$('story-btn').onclick=openStory;$('help-btn').onclick=()=>$('help-dialog').showModal();$('reset-btn').onclick=()=>$('reset-dialog').showModal();$('confirm-reset').onclick=()=>{stopLesson();$('reset-dialog').close();init();toast('最初の状態に戻しました。');};
window.Hematite={get state(){return state;},get page(){return page;},tech,cost,income,powerInfo,buildReason,doResearch,build,survey,move,claimOutpost,endTurn,recruit,movePatrol,attack,enemyPhase,reset:init,selectTech,selectTile:(x,y)=>{selectedTile=key(x,y);renderMap();},switchPage,render};
init();
if(new URLSearchParams(location.search).has('view')&&new URLSearchParams(location.search).get('view')==='research'){selectedTech='electrolysis';switchPage('research');}
if(new URLSearchParams(location.search).has('overview')){fullMap=true;renderMap();}
if(new URLSearchParams(location.search).has('test')){const script=document.createElement('script');script.src='tests/smoke.js';document.body.appendChild(script);}
})();
